$ErrorActionPreference = "Stop"

function Write-PatchedFile {
    param([string]$path, [string]$b64, [string]$label)

    if (-not (Test-Path -LiteralPath $path)) {
        Write-Host "ERROR: Could not find $path from current directory." -ForegroundColor Red
        Write-Host "Run this script from the root of your NaijaDrops checkout." -ForegroundColor Red
        exit 1
    }

    Write-Host "Fixing: $label" -ForegroundColor Cyan
    Write-Host "  File: $path" -ForegroundColor Cyan

    $timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
    $backupPath = "$path.$timestamp.bak"
    Copy-Item -LiteralPath $path -Destination $backupPath -Force
    Write-Host "  Backup written to $backupPath" -ForegroundColor Yellow

    $bytes = [System.Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($path, $bytes)

    Write-Host "  Written successfully." -ForegroundColor Green
    Write-Host ""
}

$patchedFiles = New-Object System.Collections.Generic.List[string]

$b64_1 = ""
$path1 = "src/app/tracking/[orderId]/page.jsx"
Write-PatchedFile -path $path1 -b64 $b64_1 -label "Light theme: fix washed-out radar rings on the Finding a Rider screen"
$patchedFiles.Add($path1)

$b64_2 = ""
$path2 = "src/app/rider/(main)/dashboard/page.jsx"
Write-PatchedFile -path $path2 -b64 $b64_2 -label "Accept-job button: add loading state so it can't look stuck/unresponsive"
$patchedFiles.Add($path2)

$b64_3 = ""
$path3 = "src/components/rider/IncomingOrderCard.jsx"
Write-PatchedFile -path $path3 -b64 $b64_3 -label "Accept-job button: wire in spinner + disabled state while accepting"
$patchedFiles.Add($path3)

git add $patchedFiles
git commit -m "Fix washed-out radar rings in light mode; add loading state to job-accept buttons"

Write-Host ""
Write-Host "All changes applied and committed locally." -ForegroundColor Green
Write-Host "Push when ready with: git push" -ForegroundColor Cyan
